// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(address caller, address initiator, address from, uint256 id, bytes calldata data) public {
        vm.prank(caller);
        bytes4 result = c.onERC721Received(initiator, from, id, data);
        assertTrue(result == bytes4(keccak256("onERC721Received(address,address,uint256,bytes)")));
    }
}
